def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: a :class:`datetime.timedelta` instance or None
    :return: an int representing the total number of seconds, or the original
             value if it is not a timedelta.
    """
    if value is None:
        return None
    try:
        return int(value.total_seconds())
    except AttributeError:
        return value

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: The dehydrated value, or ``None`` if *value* is ``None``.
    """
    if value is None:
        return None
    if not hasattr(value, "isoformat"):
        raise TypeError("value must be a datetime.time instance")
    return value.isoformat()

def keys(self):
    """ Return the keys of the record.
    :return: list of key names
    """
    # Attempt to return keys from a stored record if it exists,
    # otherwise return an empty list or the instance's own attributes.
    if hasattr(self, "_record") and isinstance(self._record, dict):
        return list(self._record.keys())
    try:
        return list(self.__dict__.keys())
    except Exception:
        return []

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    handlers = getattr(cls, "_protocol_handlers", {})
    if protocol_version is None:
        return dict(handlers)
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    handler = handlers.get(protocol_version)
    if handler is not None:
        return {protocol_version: handler}
    return {}

def index(self, key):
    """
    Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(f'Key not found: {key!r}')

def values(self, *keys):
        """ Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        if not hasattr(self, "_items"):
            raise AttributeError("The object does not have an '_items' attribute.")
        # Ensure the underlying collection behaves like a mapping
        if not isinstance(self._items, dict):
            raise TypeError("The '_items' attribute must be a dictionary.")
        item_values = list(self._items.values())
        if not keys:
            return item_values
        result = []
        for k in keys:
            if isinstance(k, int):
                if k < 0 or k >= len(item_values):
                    raise IndexError(
                        f"Index {k} is out of bounds for the values list "
                        f"(size {len(item_values)})."
                    )
                result.append(item_values[k])
            else:
                if k not in self._items:
                    raise KeyError(f"Key {k!r} does not exist in the record.")
                result.append(self._items[k])
        return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Determine the ordered list of field names.  The class is expected
    # to provide either a list of names in ``self._keys`` or a mapping
    # of name->index in ``self._keys``.  Fallback to ``self._fields`` if
    # another attribute is present.
    if hasattr(self, "_keys"):
        if isinstance(self._keys, dict):
            field_names = list(self._keys.keys())
        else:
            field_names = list(self._keys)
    elif hasattr(self, "_fields"):
        field_names = list(self._fields)
    else:
        # If we cannot determine the field names, fall back to all
        # attributes of the instance.
        field_names = [k for k in vars(self).keys() if not k.startswith("_")]
    values = [getattr(self, name, None) for name in field_names]

    # If no specific keys were requested, return all values.
    if not keys:
        return dict(zip(field_names, values))

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Treat ``key`` as a positional index.
            if key < 0 or key >= len(field_names):
                raise IndexError("Index %r is out of bounds" % (key,))
            field_name = field_names[key]
            result[field_name] = values[key]
        else:
            # Treat ``key`` as a field name.
            if key in field_names:
                idx = field_names.index(key)
                result[key] = values[idx]
            else:
                result[key] = None
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    namespace = {}
    for f in fields:
        namespace[f] = None
    namespace['__srid_map__'] = srid_map
    return type(name, (Point,), namespace)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not s:
        return ()
    # split on dot and ignore any non-digit suffixes
    result = []
    for part in s.strip().split('.'):
        # extract the leading numeric component from each part
        num = ''
        for ch in part:
            if ch.isdigit():
                num += ch
            else:
                break
        if num:
            try:
                result.append(int(num))
            except ValueError:
                # ignore non-numeric parts
                pass
    return tuple(result)

