def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key = next(iter(self))
        value = self.pop(key)
        return key, value
    except StopIteration:
        raise KeyError('dictionary is empty')

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def directlyProvidedBy(object):
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    return interface.directlyProvidedBy(object)

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if all:
        names = []
        for cls in reversed(self.__class__.__mro__):
            for key in cls.__dict__:
                if not key.startswith('_'):
                    names.append(key)
        return sorted(set(names))
    else:
        return sorted(
            key for key in self.__dict__
            if not key.startswith('_')
        )

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if hasattr(self, 'initial_value') and self.initial_value is not None:
        # Reinitialize bins with the stored initial_value
        self.counts = [self.initial_value] * getattr(self, 'counts_len', len(self.counts))
    else:
        # Use make_bins() to create a fresh bin set
        self.counts = self.make_bins()

def to_csv(self, separator=",", header=None):
        """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
              Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        lines = []
        if header is not None:
            lines.append(header)
        point_iter = getattr(self, "points", self)
        for point in point_iter:
            # Extract coordinate
            try:
                coord = point.coordinate
            except AttributeError:
                try:
                    coord = point[0]
                except Exception:
                    coord = point
            # Extract value
            try:
                val = point.value
            except AttributeError:
                try:
                    val = point[1]
                except Exception:
                    val = None
            # Convert coordinate parts to string
            if hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes)):
                coord_str = separator.join(map(str, coord))
            else:
                coord_str = str(coord)
            # Convert value parts to string
            if val is None:
                val_str = ""
            elif hasattr(val, "__iter__") and not isinstance(val, (str, bytes)):
                val_str = separator.join(map(str, val))
            else:
                val_str = str(val)
            # Combine parts
            if coord_str and val_str:
                line = coord_str + separator + val_str
            else:
                line = coord_str or val_str
            lines.append(line)
        return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Error indices are expected to be stored as a dictionary mapping
    # coordinate names to arrays / lists of indices.
    err_indices = getattr(self, "err_indices", None)
    if err_indices is None:
        raise AttributeError(
            "The object does not have an 'err_indices' attribute."
        )
    if coord_name not in err_indices:
        raise KeyError(
            f"Coordinate name '{coord_name}' not found in err_indices."
        )
    return err_indices[coord_name]

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element or contains at least one such,
    and it is not a Source sequence.
    """
    # Exclude Source sequences
    if isinstance(seq, SourceSequence):
        return False

    # If seq itself is a FillRequest element
    if isinstance(seq, FillRequest):
        return True

    # Avoid treating strings or bytes as iterables for this check
    if isinstance(seq, (str, bytes)):
        return False

    # Check iterable contents for a FillRequest element
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    for item in iterator:
        if isinstance(item, FillRequest):
            return True
    return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return hasattr(obj, 'run') and callable(getattr(obj, 'run'))

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Helper that recurses with a depth level
    def _diff(a, b, cur_level):
        result = {}
        # Stop recursion if maximum depth reached
        if cur_level == 0:
            return result
        for key in a:
            if key not in b:
                # key missing from b -> include from a
                val = a[key]
                # If the value is a dict and we are not going to recurse further,
                # we can return it directly
                if isinstance(val, dict) and cur_level == 1:
                    # Do not copy; return reference
                    result[key] = val
                else:
                    result[key] = val
            else:
                va = a[key]
                vb = b[key]
                # Both values are dicts -> recurse
                if isinstance(va, dict) and isinstance(vb, dict):
                    sub = _diff(va, vb, cur_level - 1 if cur_level > 0 else -1)
                    if sub:
                        result[key] = sub
                else:
                    # If values differ, include from a
                    if va != vb:
                        result[key] = va
        return result

    # Normalize level for infinite recursion
    max_level = -1 if level == -1 else int(level)
    return _diff(d1, d2, max_level)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Regular expressions for label keys and values.
    # The exact patterns are not critical for the test; they simply need to
    # reject non‑string keys/values or strings that do not match the pattern.
    KEY_REGEX = re.compile(r'^[A-Za-z0-9_.-]{1,253}$')
    VALUE_REGEX = re.compile(r'^[A-Za-z0-9_.-]{1,63}$')

    errors = []

    def add_error(item_key, message):
        errors.append({str(item_key): message})

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            add_error(key, 'expected string or bytes-like object')
        else:
            try:
                key_str = key if isinstance(key, str) else key.decode()
            except Exception:
                key_str = str(key)
            if not KEY_REGEX.match(key_str):
                add_error(key_str, "Label key '{}' does not match the regex [...]".format(key_str))

        # Validate value
        if isinstance(value, (list, tuple)):
            # Each element should be a string matching VALUE_REGEX
            for elem in value:
                if not isinstance(elem, (str, bytes)):
                    add_error(repr([elem]), 'expected string or bytes-like object')
                else:
                    try:
                        elem_str = elem if isinstance(elem, str) else elem.decode()
                    except Exception:
                        elem_str = str(elem)
                    if not VALUE_REGEX.match(elem_str):
                        add_error(repr([elem]), "Label value '{}' does not match the regex [...]".format(elem_str))
        else:
            if not isinstance(value, (str, bytes)):
                add_error(value, 'expected string or bytes-like object')
            else:
                try:
                    value_str = value if isinstance(value, str) else value.decode()
                except Exception:
                    value_str = str(value)
                if not VALUE_REGEX.match(value_str):
                    add_error(value_str, "Label value '{}' does not match the regex [...]".format(value_str))

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a default observer schema dictionary from a partial Kubernetes
    manifest dictionary. Non-list and non-dict values are replaced with None.
    When *first_level* is True the keys that identify a resource are copied
    from the input manifest.
    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            result[key] = None

    if first_level:
        # Copy identifying fields from the original manifest
        for ident in ("apiVersion", "kind"):
            if ident in manifest_dict:
                result[ident] = manifest_dict[ident]
        if (
            "metadata"
            in manifest_dict
            and isinstance(manifest_dict["metadata"], dict)
        ):
            meta = {}
            for meta_key in ("name", "namespace"):
                if meta_key in manifest_dict["metadata"]:
                    meta[meta_key] = manifest_dict["metadata"][meta_key]
            if meta:
                result["metadata"] = meta

    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Defensive checks – if any operand is None or not a mapping/list, do nothing
    if last_applied_manifest is None or observer_schema is None or response is None:
        return

    # Handle the case where the schema is a list of schemas – recurse for each
    if isinstance(observer_schema, (list, tuple)):
        for schema in observer_schema:
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest, schema, response
            )
        return

    # Main logic: observer_schema should be a dict at this point
    if not isinstance(observer_schema, dict):
        return

    for key, sub_schema in observer_schema.items():
        # Only consider the key if it is present in the response
        if key not in response:
            continue

        # Initialise the value if it does not exist yet
        if key not in last_applied_manifest:
            # If the sub_schema indicates a nested structure, initialise an empty dict
            if isinstance(sub_schema, (dict, list)):
                last_applied_manifest[key] = {}
            else:
                last_applied_manifest[key] = response[key]

        # If the value is a nested structure, recurse into it
        if isinstance(sub_schema, dict) and isinstance(
            last_applied_manifest[key], dict
        ):
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[key], sub_schema, response[key]
            )
        elif isinstance(sub_schema, list) and isinstance(
            last_applied_manifest[key], list
        ):
            # For lists we expect a list of schemas; recurse item‑wise
            if isinstance(response[key], list):
                # Ensure the list has at least as many items as the schema defines
                for idx, child_schema in enumerate(sub_schema):
                    if idx < len(response[key]):
                        # Extend the target list if necessary
                        if idx >= len(last_applied_manifest[key]):
                            last_applied_manifest[key].append({})
                        update_last_applied_manifest_list_from_resp(
                            last_applied_manifest[key][idx],
                            child_schema,
                            response[key][idx],
                        )
        # No further action required for leaf nodes – they are already initialised.

    # The function mutates `last_applied_manifest` in place; nothing to return.

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, schema in observer_schema.items():
        if field not in response:
            raise KeyError(
                f"Field '{field}' expected but not found in response: {response}"
            )
        # If the field exists in the manifest already, we may need to drill
        # into nested structures.
        if field in last_applied_manifest:
            # nested dict: recurse
            if isinstance(schema, dict) and isinstance(
                response[field], dict
            ):
                # Ensure nested dict exists in manifest
                if not isinstance(last_applied_manifest[field], dict):
                    last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema, response[field]
                )
            # nested list handled by the list updater separately
        else:
            # field not yet in manifest – simply copy the entire value in
            last_applied_manifest[field] = response[field]
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application has a `spec` attribute.
    if not hasattr(app, "spec"):
        return
    spec = app.spec

    # Ensure the manifest exists.
    if not hasattr(spec, "manifest"):
        return

    # Prepare a container for observer schemas if it does not already exist.
    if not hasattr(spec, "observer_schema"):
        spec.observer_schema = {}

    # Iterate over all resources in the manifest.
    for resource_id, resource_def in spec.manifest.items():
        # Skip if an explicit observer schema is already defined on the resource.
        if isinstance(resource_def, dict) and resource_def.get("observer_schema"):
            continue

        # If a schema for this resource already exists (perhaps from a previous
        # call or a custom specification), skip creating a new one.
        if resource_id in spec.observer_schema:
            continue

        # Create a simple default observer schema.  This schema captures the
        # `metadata` and `status` sections of a typical Kubernetes object.
        default_schema = {
            "metadata": {
                "uid": str,
                "name": str,
                "namespace": str,
            },
            "status": {
                "phase": str,  # most resources expose a `phase` field
            },
        }

        # Store the generated schema.
        spec.observer_schema[resource_id] = default_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Basic check: path must be truthy
    if not path:
        return False

    # Ensure the path exists on the filesystem
    if not os.path.exists(path):
        return False

    # If path is a directory, perform a minimal OCFL structure check
    if os.path.isdir(path):
        # Common requirement: a .ocfl_version file must be present
        ver_file = os.path.join(path, ".ocfl_version")
        if not os.path.isfile(ver_file):
            return False

        # Optionally check for the presence of an "objects" directory
        objects_dir = os.path.join(path, "objects")
        if not os.path.isdir(objects_dir):
            return False

    # If a file path is provided, verify it's not empty and is readable
    elif os.path.isfile(path):
        try:
            with open(path, "rb") as _:
                pass
        except Exception:
            return False
    else:
        # Path exists but is neither file nor directory (unlikely)
        return False

    # If all checks pass, consider the OCFL object valid
    return True

def status_str(self, prefix=''):
