def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Assume the validation log is stored in an attribute named `log` or `entries`.
    log = getattr(self, "log", None) or getattr(self, "entries", None) or []
    if not log:
        return f"{prefix}No logs available."
    lines = []
    for entry in log:
        if isinstance(entry, dict):
            # Convert dictionary entries into key=value pairs.
            parts = []
            for k, v in entry.items():
                parts.append(f"{k}={v}")
            line = ", ".join(parts)
        else:
            line = str(entry)
        lines.append(f"{prefix}{line}")
    return "\n".join(lines)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure digests_used is a set for efficient lookup
    digests_used_set = set(digests_used)
    # Use the internal digests mapping (assuming it is stored in self._digests)
    digests_available = getattr(self, "_digests", {})
    missing = []
    unused = []
    for file_entry in manifest_files:
        digest = file_entry.get("digest")
        if not digest:
            continue
        # Check that the digest is in the known digests
        if digest not in digests_available:
            missing.append(digest)
        # Check that the digest is actually used
        if digest not in digests_used_set:
            unused.append(digest)
    if missing:
        raise ValueError(f"Missing digests in manifest: {', '.join(missing)}")
    if unused:
        raise ValueError(f"Digests in manifest were not marked as used: {', '.join(unused)}")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # If the inventory or requested version is not present, return an empty map
    if not inventory or version not in inventory:
        return {}

    # Determine the order of versions (sort by string order, you can replace with
    # any version comparison logic if necessary)
    sorted_versions = sorted(inventory.keys())

    # Find the starting index for the requested version
    try:
        start_index = sorted_versions.index(version)
    except ValueError:
        return {}

    logical_map = {}

    # Gather all content files from the requested version and any later versions
    for v in sorted_versions[start_index:]:
        version_inventory = inventory.get(v, {})
        for logical_path, files in version_inventory.items():
            # Ensure the entry exists in the result map
            if logical_path not in logical_map:
                logical_map[logical_path] = set()
            # Add all file references to the set
            logical_map[logical_path].update(files if isinstance(files, (list, set, tuple)) else [files])

    return logical_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    required_keys = {"files", "algorithm", "checksum"}
    missing = required_keys - set(fixity.keys())
    if missing:
        raise ValueError(f"Missing keys in fixity block: {', '.join(sorted(missing))}")

    files = fixity["files"]
    if not isinstance(files, list):
        raise ValueError("Fixity 'files' must be a list")

    for f in files:
        if f not in manifest_files:
            raise ValueError(f"File '{f}' in fixity block not present in manifest")

    return True

