def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Parameters
    ----------
    indent : int, optional
        Indentation level used for pretty printing.
    debug : bool, optional
        If True, append debug information such as the object's type and id.

    Returns
    -------
    str
        The pretty-printed string representation of the object.
    """
    import pprint
    try:
        # Prefer the object's dictionary if available
        if hasattr(self, "__dict__"):
            data = self.__dict__
        elif hasattr(self, "__slots__"):
            data = {slot: getattr(self, slot) for slot in self.__slots__}
        else:
            data = self

        if isinstance(data, (dict, list, tuple, set)):
            formatted = pprint.pformat(data, indent=indent)
        else:
            formatted = repr(data)

        if debug:
            formatted += f"\n[DEBUG] type={type(self).__name__}, id={id(self)}"

        return formatted
    except Exception:
        # Fallback to a simple repr if anything goes wrong
        return repr(self)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def _simplify(expr):
        # Recursively simplify subexpressions
        if isinstance(expr, (list, tuple)):
            if len(expr) == 3 and isinstance(expr[0], str) and expr[0] in ('&', '|'):
                left = _simplify(expr[1])
                right = _simplify(expr[2])
                op = expr[0]
                # Absorption: A & (A | B) = A, A | (A & B) = A
                if op == '&' and isinstance(right, (list, tuple)) and len(right) == 3 and right[0] == '|':
                    if left == right[1]:
                        return left
                if op == '|' and isinstance(right, (list, tuple)) and len(right) == 3 and right[0] == '&':
                    if left == right[1]:
                        return left
                # Negative absorption: A & (~A | B) = A & B
                if op == '&' and isinstance(right, (list, tuple)) and len(right) == 3 and right[0] == '|':
                    if (isinstance(right[1], (list, tuple)) and len(right[1]) == 2
                        and right[1][0] == '~' and left == right[1][1]):
                        # A & (~A | B) => A & B
                        return ('&', left, right[2])
                # Negative absorption: A | (~A & B) = A | B
                if op == '|' and isinstance(right, (list, tuple)) and len(right) == 3 and right[0] == '&':
                    if (isinstance(right[1], (list, tuple)) and len(right[1]) == 2
                        and right[1][0] == '~' and left == right[1][1]):
                        # A | (~A & B) => A | B
                        return ('|', left, right[2])
                return (op, left, right)
            elif len(expr) == 2 and isinstance(expr[0], str) and expr[0] == '~':
                return ('~', _simplify(expr[1]))
        return expr

    return [_simplify(arg) for arg in args]

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    import os
    base = os.path.dirname(__file__) if '__file__' in globals() else ''
    version_file = os.path.join(base, 'VERSION')
    try:
        with open(version_file, 'r', encoding='utf-8') as f:
            return f.read().strip()
    except Exception:
        return 'unknown'

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Accept a dict or an iterable of (key, value) pairs
    if isinstance(pieces, dict):
        mapping = pieces
    else:
        try:
            mapping = dict(pieces)
        except Exception:
            raise TypeError("pieces must be a dict or iterable of key/value pairs")

    if style is None:
        style = 'short'

    if style == 'short':
        # Build a dotted format: major.minor.patch
        major = mapping.get('major', 0)
        minor = mapping.get('minor', 0)
        patch = mapping.get('patch', 0)
        return f"{major}.{minor}.{patch}"
    elif style == 'long':
        # Verbose, human‑readable description
        parts = []
        if 'major' in mapping:
            parts.append(f"Major {mapping['major']}")
        if 'minor' in mapping:
            parts.append(f"Minor {mapping['minor']}")
        if 'patch' in mapping:
            parts.append(f"Patch {mapping['patch']}")
        if 'pre_release' in mapping:
            parts.append(f"Pre‑release {mapping['pre_release']}")
        if 'build' in mapping:
            parts.append(f"Build {mapping['build']}")
        return ', '.join(parts)
    elif style == 'json':
        import json
        return json.dumps(mapping)
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Convert pieces to a single string (handles lists, tuples, or single strings)
    s = ''
    if isinstance(pieces, (list, tuple, set)):
        s = ' '.join(map(str, pieces))
    else:
        s = str(pieces)
    return '.' if '+' in s else '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the full command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        # Ensure args is a sequence
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(args)

    if verbose:
        # Show the command being executed
        print(f"Running command: {' '.join(cmd)}")

    # Determine stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    # Execute the command
    process = subprocess.Popen(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=stderr_option,
        env=env
    )
    stdout, stderr = process.communicate()

    # Decode output for readability
    try:
        stdout_text = stdout.decode() if stdout else ''
    except Exception:
        stdout_text = str(stdout)
    try:
        stderr_text = stderr.decode() if stderr else ''
    except Exception:
        stderr_text = str(stderr)

    if process.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=process.returncode,
            cmd=cmd,
            output=stdout_text,
            stderr=stderr_text,
        )

    return stdout_text

def register_vcs_handler(vcs, method):  # tyoe: (str, str) -> typing.Callable  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Gather all objects from the hierarchy
        try:
            objects = list(self._enumerate_objects())
        except AttributeError:
            # Fallback if no dedicated enumerator is defined
            objects = list(self.root.iteratesubobjects()) if hasattr(self, 'root') else []

        num_objects = 0
        good_objects = 0
        warnings = []

        for obj in objects:
            num_objects += 1
            valid = True
            # Validate object structure and contents if requested
            if validate_objects:
                try:
                    valid &= self._validate_object(obj)
                except Exception as exc:
                    valid = False
                    warnings.append(f"Validation error for object {obj}: {exc}")

            # Check digest/hash integrity if requested
            if check_digests:
                try:
                    valid &= self._check_digest(obj)
                except Exception as exc:
                    valid = False
                    warnings.append(f"Digest check failed for object {obj}: {exc}")

            if valid:
                good_objects += 1
            elif show_warnings:
                print(f"Object {obj} failed validation: {'valid' if valid else 'invalid'}")

        if show_warnings and warnings:
            for w in warnings:
                print("WARNING:", w)

        return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    # Detect if the version string is numeric with leading zeros
    has_leading_zeros = version.isdigit() and len(version) > 1 and version.startswith("0")
    try:
        number = int(version)
    except ValueError:
        # If the string cannot be converted to an integer, return it unchanged
        return version
    next_number = number + 1
    if has_leading_zeros:
        # Preserve the original padding length
        return str(next_number).zfill(len(version))
    return str(next_number)

def parser_flags(parser):
