def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])
    while queue:
        c = queue.pop()
        seen.add(c)
        for sub in c.__subclasses__():
            if sub not in seen:
                queue.add(sub)
    seen.discard(cls)
    return seen

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    # Prefer os.uname if available, otherwise fallback to sys.platform
    try:
        if hasattr(os, 'uname'):
            return os.uname().sysname == 'Darwin'
    except Exception:
        # In case os.uname exists but fails
        pass
    import sys
    return sys.platform.startswith('darwin')

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess

    # Determine a suitable directory name inside tmp_path
    base_name = os.path.basename(archive_path)
    # Strip common compressed archive suffixes
    for suffix in ('.tar.gz', '.tgz', '.tar.bz2', '.zip'):
        if base_name.endswith(suffix):
            base_name = base_name[: -len(suffix)]
            break
    else:
        base_name = os.path.splitext(base_name)[0]

    # Destination directory for extracted files
    dest_dir = os.path.join(tmp_path, base_name)
    os.makedirs(dest_dir, exist_ok=True)

    # Construct extraction command based on archive type
    if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
        cmd = ['tar', '-xzf', archive_path, '-C', dest_dir]
    elif archive_path.endswith('.tar.bz2'):
        cmd = ['tar', '-xjf', archive_path, '-C', dest_dir]
    elif archive_path.endswith('.zip'):
        cmd = ['unzip', '-q', '-o', archive_path, '-d', dest_dir]
    else:
        raise ValueError(f'Unsupported archive type for file: {archive_path}')

    # Run the extraction subprocess
    try:
        subprocess.run(cmd, check=True)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Extraction failed for {archive_path}") from exc

    # Optionally rename the top-level folder if filename is provided
    if filename:
        extracted_path = os.path.join(dest_dir, base_name)
        new_path = os.path.join(dest_dir, filename)
        if not os.path.exists(extracted_path):
            # In some archives the top-level directory might be named differently;
            # use the first non-hidden directory found.
            entries = [e for e in os.listdir(dest_dir) if not e.startswith('.')]
            if entries:
                extracted_path = os.path.join(dest_dir, entries[0])
        if os.path.exists(extracted_path):
            os.rename(extracted_path, new_path)
            dest_dir = new_path

    return f'file://{dest_dir}'

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            cwd=ignored,
            stderr=subprocess.STDOUT,
            text=True
        )
    except subprocess.CalledProcessError:
        return ''
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    # Direct string comparison for common localhost representations
    if host.lower() in ('localhost', '127.0.0.1', '::1'):
        return True
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for info in infos:
        sockaddr = info[4]
        ip = sockaddr[0]
        if ip == '::1':
            return True
        if ip.startswith('127.'):
            return True
    return False

def is_gitbash():
