def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''

    import os
    import logging
    import json
    import yaml
    import toml

    def _resolve_vars(obj):
        if isinstance(obj, dict):
            return {k: _resolve_vars(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_vars(v) for v in obj]
        elif isinstance(obj, str):
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                var = match.group(1)
                return os.environ.get(var, match.group(0))
            return pattern.sub(repl, obj)
        else:
            return obj

    result_dict = {}
    error_logs = []

    for fname in config_filenames:
        try:
            with open(fname, 'r') as fd:
                raw = fd.read()
            # Detect format by extension
            if fname.lower().endswith('.toml'):
                cfg = toml.loads(raw)
            elif fname.lower().endswith(('.yaml', '.yml')):
                cfg = yaml.safe_load(raw)
            elif fname.lower().endswith('.json'):
                cfg = json.loads(raw)
            else:
                # Fallback: try common formats in order
                try:
                    cfg = toml.loads(raw)
                except Exception:
                    try:
                        cfg = yaml.safe_load(raw)
                    except Exception:
                        cfg = json.loads(raw)
            if overrides:
                if isinstance(cfg, dict):
                    cfg = {**cfg, **overrides}
            if resolve_env:
                cfg = _resolve_vars(cfg)
            result_dict[fname] = cfg
        except Exception as e:
            record = logging.LogRecord(
                name=fname,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=e
            )
            error_logs.append(record)

    return result_dict, error_logs

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    else:
        return obj

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Convert each raw string into a Bookmark instance, skipping empty strings.
    bookmarks = []

    for raw in values:
        if not raw:
            continue

        # Prefer an explicit from_raw classmethod if it exists, otherwise
        # instantiate the Bookmark class with the raw string directly.
        if hasattr(Bookmark, "from_raw"):
            try:
                bookmark = Bookmark.from_raw(raw)
            except Exception:
                # Fallback to direct construction if parsing fails.
                bookmark = Bookmark(raw)
        else:
            bookmark = Bookmark(raw)

        bookmarks.append(bookmark)

    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Consider something iterable (excluding strings/bytes) as a sequence
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
        return seq, type(seq)
    # Otherwise wrap the value in a list
    derived = [seq]
    return derived, type(derived)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Determine the list of required attributes from the interface.
    if isinstance(iface, (list, tuple, set)):
        required = list(iface)
    else:
        # Filter out private attributes and non-callables.
        required = [name for name in dir(iface)
                    if not name.startswith('_') and callable(getattr(iface, name, None))]

    missing = []
    for name in required:
        if not hasattr(candidate, name):
            missing.append(name)
            continue
        attr = getattr(candidate, name)
        if not callable(attr):
            missing.append(name)

    if missing:
        raise TypeError(f'{candidate!r} does not implement required methods: {missing}')

    # When tentative is False, perform a stricter check: try instantiating
    # the candidate (if it's a class) and ensure all methods are not abstract.
    if not tentative and isinstance(candidate, type):
        try:
            obj = candidate()
        except Exception as exc:
            raise TypeError(f'Cannot instantiate candidate {candidate!r}: {exc}') from exc
        for name in required:
            method = getattr(obj, name)
            try:
                method()
            except NotImplementedError:
                raise TypeError(f'Abstract method {name} not implemented in {candidate!r}')

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""
    # If an explicit metaclass was supplied, it must be compatible with all bases.
    if explicit_mc is not None:
        for base in bases:
            base_meta = type(base)
            if not issubclass(base_meta, explicit_mc):
                raise TypeError(
                    f"metaclass conflict: {base_meta.__name__} is not a "
                    f"subclass of explicit metaclass {explicit_mc.__name__}"
                )
        return explicit_mc

    # No explicit metaclass; determine the most derived common metaclass.
    if not bases:
        return type  # default metaclass for new-style classes

    # Collect the metaclass of each base.
    meta_candidates = [type(b) for b in bases]

    # Build the MRO lists for each metaclass candidate.
    mro_lists = [mc.mro() for mc in meta_candidates]

    # Find the first metaclass in the first MRO that is present in all others.
    for candidate in mro_lists[0]:
        if all(candidate in mros for mros in mro_lists[1:]):
            return candidate

    raise TypeError("metaclass conflict: no common metaclass found")

def pop(self, key, default=__marker):
    """ D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised. """
    try:
        return super().pop(key)
    except KeyError:
        if default is __marker:
            raise
        return default

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    return super().popitem(last=False)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key, value = dict.popitem(self)
        return key, value
    except KeyError:
        raise

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dict is empty')
    import random
    key = random.choice(list(self))
    return key, self.pop(key)

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    pattern = r'\b(?P<field>\w+)\s+IN\s*\((?P<values>.+?)\)'
    return re.compile(pattern, flags=re.UNICODE | re.MULTILINE | re.IGNORECASE)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    def replace_url(match):
        url = match.group(0)
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'
    url_pattern = re.compile(r'https?://[^\s<]+')
    return url_pattern.sub(replace_url, text)

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req) as resp:
            return resp.getheader('content-type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    if not tag:
        return False
    allowed = set("-_")
    return all(c.isalnum() or c in allowed for c in tag)

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    base = url.rstrip("/")
    # Use custom document path if provided, otherwise default to the standard NodeInfo 1.0 path
    if document_path:
        # If the custom path is absolute, use it directly; otherwise, prepend the base URL
        href = document_path if document_path.startswith("http://") or document_path.startswith("https://") else f"{base}{document_path}"
    else:
        href = f"{base}/.well-known/nodeinfo/1.0"
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Helper to strip namespace
    def _strip_ns(tag):
        return tag.split("}")[-1] if "}" in tag else tag

    def _parse_json_webfinger(data):
        """
        Parse modern JSON webfinger. Return the dictionary as is.
        """
        # Ensure keys are present; provide default empty listings if missing
        result = {
            "subject": data.get("subject"),
            "aliases": data.get("aliases", []),
            "links": data.get("links", []),
        }
        return result

    def _parse_xrd_webfinger(xrd_root):
        """
        Parse old XRD (XML) webfinger. Convert to a dict with similar keys.
        """
        subject_elem = xrd_root.find("*[local-name()='Subject']")
        subject = subject_elem.text if subject_elem is not None else None

        aliases = []
        for alias in xrd_root.findall("*[local-name()='Alias']"):
            if alias.text:
                aliases.append(alias.text)

        links = []
        for link in xrd_root.findall("*[local-name()='Link']"):
            link_dict = {}
            for attr in ["rel", "type", "href", "name"]:
                if attr in link.attrib:
                    link_dict[attr] = link.attrib[attr]
            # Node attributes can have 'rel' empty; skip if missing
            if "rel" in link_dict:
                links.append(link_dict)

        return {"subject": subject, "aliases": aliases, "links": links}

    # Attempt to parse as JSON first
    try:
        json_obj = json.loads(document)
        # Basic validation: ensure it has at least 'subject' or 'links'
        if isinstance(json_obj, dict) and ("subject" in json_obj or "links" in json_obj):
            return _parse_json_webfinger(json_obj)
    except Exception:
        pass  # Fall back to XML parsing

    # Try XML parsing
    try:
        root = ET.fromstring(document)
        # The root may be XRD or just any element; look for Subject, Alias, Link
        return _parse_xrd_webfinger(root)
    except Exception:
        # If parsing fails, return empty dict
        return {}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        _, host = handle.split("@", 1)
    except ValueError:
        # handle is not of the form user@domain
        return None

    url = f"https://{host}/.well-known/webfinger?resource={quote('acct:' + handle)}"

    try:
        with closing(urllib.request.urlopen(url)) as response:
            return response.read().decode("utf-8")
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    try:
        file_paths = []
        # Ensure directories are iterable
        if isinstance(settings_dirs, (str, bytes)):
            dirs = [settings_dirs]
        else:
            dirs = list(settings_dirs)

        for directory in dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if spec_option is None or fname.endswith(spec_option):
                    file_paths.append(os.path.join(directory, fname))

        return sorted(file_paths)
    except OSError:
        return []

