    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content cannot be None")

        try:
            spec = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Error parsing YAML content: {exc}")

        if not isinstance(spec, dict):
            raise IRValidatorException("Spec content must be a mapping.")

        # The class may define a list of required fields; default to empty.
        required = getattr(cls, "required_fields", [])
        missing = [field for field in required if field not in spec]
        if missing:
            raise IRValidatorException(
                f"Missing required field(s): {', '.join(missing)}"
            )

        return spec

