def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        # First pass: handle any includes at the current level
        for key, val in list(parser_dict.items()):
            if isinstance(val, dict) and 'include' in val:
                include_items = val.pop('include')
                # Normalize to a list of keys
                if isinstance(include_items, str):
                    include_items = [include_items]
                elif not isinstance(include_items, (list, tuple)):
                    continue  # nothing to include
                merged = {}
                for inc_key in include_items:
                    inc_def = parser_dict.get(inc_key)
                    if inc_def is None:
                        # silently ignore missing includes
                        continue
                    if isinstance(inc_def, dict):
                        merged.update(inc_def)
                # Merge the rest of the current dict values after removal
                merged.update(val)
                parser_dict[key] = merged
        # Recursive pass for nested dictionaries
        for val in parser_dict.values():
            if isinstance(val, dict):
                self._include_groups(val)

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources. """
        defaults = {}
        # Extract defaults from the function signature if available
        try:
            defaults = _get_defaults(self.func)
        except AttributeError:
            pass

        # Merge defaults from the spec object if present
        spec = getattr(self, 'spec', None)
        if spec is not None:
            if hasattr(spec, 'defaults'):
                defaults.update(spec.defaults)
            elif hasattr(spec, 'to_dict'):
                defaults.update(spec.to_dict())
            elif hasattr(spec, '__dict__'):
                defaults.update(spec.__dict__)

        # Merge defaults from the default_spec if present
        default_spec = getattr(self, '_default_spec', None)
        if default_spec is not None:
            if hasattr(default_spec, 'defaults'):
                defaults.update(default_spec.defaults)
            elif hasattr(default_spec, 'to_dict'):
                defaults.update(default_spec.to_dict())
            elif hasattr(default_spec, 'items'):
                defaults.update(dict(default_spec.items()))

        return defaults

