def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    # Helper function to evaluate a condition that can be a callable or an
    # expression string.
    def _eval_condition(cond, cmd, argdict):
        try:
            if callable(cond):
                # Try to call with (command_name, args) first then with args only
                try:
                    return bool(cond(cmd, argdict))
                except TypeError:
                    return bool(cond(argdict))
            else:
                # Treat as string expression
                return bool(eval(cond, {}, {"command_name": cmd, "args": argdict}))
        except Exception:
            return False

    for opt in options_spec:
        # Determine the option's name/key.
        opt_name = None
        if isinstance(opt, dict):
            for nkey in ("name", "arg", "id"):
                if nkey in opt:
                    opt_name = opt[nkey]
                    break
        else:
            # Assume sequence-like where first element is name.
            try:
                opt_name = opt[0]
            except Exception:
                pass

        if not opt_name:
            continue

        required_when = None
        if isinstance(opt, dict):
            required_when = opt.get("required_when")

        if required_when is None:
            continue

        if _eval_condition(required_when, command_name, args):
            required.append(opt_name)

    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    parsed_args = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        arg_spec = parsed_args.get(arg_name)
        if arg_spec is None:
            continue
        max_len = arg_spec.get('max_length')
        if max_len is None:
            continue
        try:
            length = len(value)
        except TypeError:
            # If value has no length, skip this check
            continue
        if length > max_len:
            self.abort(
                f"Argument '{arg_name}' is longer than allowed maximum length {max_len} (got length {length})"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve argument specifications from the parsed YAML configuration
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        # Skip arguments that are not defined in the specification
        arg_def = arg_defs.get(arg_name)
        if not arg_def:
            continue
        # Handle normal case where the argument definition is a dict
        if isinstance(arg_def, dict):
            choices = arg_def.get('choices')
            if choices is not None and value not in choices:
                abort(
                    f"Argument '{arg_name}' has invalid value {value!r}. "
                    f"Allowed choices: {choices}"
                )
        # Handle legacy case where arg_def might be a list of single mapping
        elif isinstance(arg_def, list) and arg_def:
            choices = arg_def[0].get('choices')
            if choices is not None and value not in choices:
                abort(
                    f"Argument '{arg_name}' has invalid value {value!r}. "
                    f"Allowed choices: {choices}"
                )

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        # Ensure that the object has min and max attributes
        if not hasattr(self, 'min') or not hasattr(self, 'max'):
            raise AttributeError("self must have 'min' and 'max' attributes for validation")

        min_val = self.min
        max_val = self.max

        for idx, val in enumerate(args):
            if val is None:
                continue
            if val < min_val or val > max_val:
                raise ValueError(
                    f"Argument {idx} ({val}) is outside the allowed range [{min_val}, {max_val}]"
                )
        return args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if vars_dict is None:
            vars_dict = {}
        if not extra_vars:
            return vars_dict
        extra_mapping = {}
        for item in extra_vars:
            if isinstance(item, dict):
                extra_mapping.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                extra_mapping[key] = value
            else:
                continue
        vars_dict.update(extra_mapping)
        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level (int, default=1)
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Resolve playbook path relative to the workspace root if not absolute
    if not os.path.isabs(playbook_path):
        pb_path = os.path.join(ir_workspace.path, playbook_path)
    else:
        pb_path = playbook_path

    # Build verbosity flag
    if verbose is None:
        verbosity = "-v"
    else:
        # Accept int or string
        try:
            level = int(verbose)
            verbosity = "-{}".format("v" * max(1, min(level, 5)))
        except Exception:
            verbosity = "-v"

    command = ["ansible-playbook", verbosity, pb_path]

    # Add extra-vars if provided
    if extra_vars:
        # Convert to JSON string for safe passing
        try:
            import json
            ev_str = json.dumps(extra_vars)
        except Exception:
            # Fallback: key=value pairs
            ev_str = " ".join(["{}={}".format(k, v) for k, v in extra_vars.items()])
        command.extend(["--extra-vars", ev_str])

    # Add additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            # Normalize key to flag form
            if not key.startswith("--"):
                key = f"--{key}"
            if isinstance(value, bool):
                if value:
                    command.append(key)
                # If False, skip adding flag
            elif value is None:
                command.append(key)
            else:
                command.extend([key, str(value)])

    # Log the command for debugging
    if ir_plugin.logger.isEnabledFor(logging.DEBUG):
        ir_plugin.logger.debug("Executing Ansible command: %s", " ".join(command))

    # Execute the command
    result = subprocess.run(command, capture_output=True, text=True, cwd=ir_workspace.path)

    if result.returncode != 0:
        raise RuntimeError(f"Ansible playbook '{pb_path}' failed with exit code {result.returncode}:\n{result.stderr}")

    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the argument specification for the given parser, if available
    parser_spec = getattr(self, "parsers", {}).get(parser_name, [])
    for opt in parser_spec:
        if opt.name in values_dict:
            try:
                values_dict[opt.name] = opt.convert(values_dict[opt.name])
            except Exception:
                # If conversion fails, keep the original string value
                pass
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import yaml

    flat_dict = {}

    # Helper to recursively flatten dictionaries
    def _flatten(d, parent_key=""):
        for key, value in d.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                _flatten(value, new_key)
            else:
                flat_dict[new_key] = value

    # Walk through all files in the directory
    for root, _, files in os.walk(plugin_dir):
        for fname in files:
            file_path = os.path.join(root, fname)
            ext = os.path.splitext(fname)[1].lower()
            try:
                if ext == ".json":
                    with open(file_path, "r", encoding="utf-8") as fh:
                        data = json.load(fh)
                elif ext in {".yaml", ".yml"}:
                    with open(file_path, "r", encoding="utf-8") as fh:
                        data = yaml.safe_load(fh)
                else:
                    continue
            except Exception:
                # Skip files that can't be parsed
                continue

            if isinstance(data, dict):
                _flatten(data)
    return flat_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    if env_var not in os.environ:
        os.environ[env_var] = str(self.config_path)
